function premiIlTasto(evento) {
  const tasto2 = evento.target?.closest?.("[data-dm-animale-azione]");
  if (!tasto2 || tasto2.disabled) return;
  evento.preventDefault();
  const quale = tasto2.dataset.dmAnimaleAzione;
  if (tasto2.dataset.dmAnimaleModo === "scegli") {
    apriIlMenu(quale, { name: tasto2.title, icon: tasto2.firstElementChild?.textContent || "🍽️" });
    return;
  }
  const chiamata = pressioneDellAzione(quale);
  if (!chiamata) return;
  tasto2.disabled = true;
  root.setTimeout?.(() => {
    tasto2.disabled = false;
  }, 3e3);
  try {
    if (typeof root.dmCallHaService === "function") {
      root.dmCallHaService(chiamata.dominio, chiamata.servizio, chiamata.dati)?.catch?.((errore) => root.console?.warn?.("[DashboardModern] animali", errore));
    } else if (typeof root.cdCallServiceJson === "function") {
      root.cdCallServiceJson(chiamata.dominio, chiamata.servizio, JSON.stringify(chiamata.dati));
    }
  } catch (_errore) {
  }
}
function installAnimaliSection() {
  if (!doc || state31.installed) return;
  state31.installed = true;
  installStyles14();
  ensureAnimaliPage();
  doc.addEventListener("click", premiIlTasto);
  doc.addEventListener("click", scegliIlFiltro);
  insegnaLaVisibilita();
  ensureAnimaliTab();
  for (const nome of ["render", "cdApplyNavVis"]) wrapFunction(nome, "__dmAnimaliSection", schedule10);
  for (const evento of [
    "dashboardmodern:legacy-ready",
    "dashboardmodern:states-ready",
    "dashboardmodern:state-changed",
    "dashboardmodern:persistence-restored",
    /* Le vasche: la storia del livello arrivata, un cambio d'acqua segnato. */
    EVENTO_ACQUARIO
  ])
    root.addEventListener?.(evento, schedule10);
  schedule10();
}

