  const readings = ENERGY_SLOTS.map(([group, field, slot]) => ({
    group,
    watts: wattsOf(states, clean(risolto?.[group]?.[field]) || (primo ? slot : ""))
  }));
  const soc = numOf(
    states,
    clean(risolto?.battery?.soc) || (primo ? "dm.energy_stato_carica_batteria" : "")
  );
