function handleClick(event) {
  if (event.target?.closest?.("[data-dm-door]")) return;
  if (event.target?.closest?.("[data-dm-stanze-indice]")) {
    state48.room = "";
    state48.signature = "";
    root.navigator?.vibrate?.(8);
    root.scrollTo?.({ top: 0, behavior: "instant" });
    schedule19();
    return;
  }
  const spegni2 = event.target?.closest?.("[data-dm-stanza-spegni]");
  if (spegni2) {
    event.preventDefault();
    event.stopPropagation();
    velo.chiedi(
      clean(spegni2.closest("[data-dm-stanza]")?.dataset.dmStanza),
      clean(spegni2.dataset.dmStanzaSpegni)
    );
    return;
  }
  const conferma = event.target?.closest?.("[data-dm-stanza-conferma]");
  if (conferma) {
    event.preventDefault();
    event.stopPropagation();
    velo.spegni(
      clean(conferma.closest("[data-dm-stanza]")?.dataset.dmStanza),
      clean(conferma.dataset.dmStanzaConferma)
    );
    return;
  }
  if (event.target?.closest?.("[data-dm-stanza-annulla]")) {
    event.preventDefault();
    event.stopPropagation();
    velo.rimetti();
    return;
  }
  const pillola2 = event.target?.closest?.("[data-dm-stanza]");
  if (pillola2) {
    state48.room = pillola2.getAttribute("data-dm-stanza") || "";
    state48.signature = "";
    root.navigator?.vibrate?.(8);
    schedule19();
    return;
  }
  const scena2 = event.target?.closest?.("[data-dm-stanza-scena]");
  if (scena2) {
    runScene(scena2.getAttribute("data-dm-stanza-scena") === "on");
    return;
  }
  const tocca2 = event.target?.closest?.("[data-dm-stanza-tocca]");
  if (tocca2) {
    event.preventDefault();
    event.stopPropagation();
    const entity2 = clean(tocca2.getAttribute("data-dm-stanza-tocca"));
    if (!entity2) return;
    const domain = entity2.split(".")[0];
    const acceso6 = accesa(entity2, allStates());
    root.navigator?.vibrate?.(8);
    chiamaServizio({
      domain,
      service: acceso6 ? "turn_off" : "turn_on",
      data: { entity_id: entity2 }
    });
    tocca2.setAttribute("aria-checked", acceso6 ? "false" : "true");
    return;
  }
  const avvia2 = event.target?.closest?.("[data-dm-stanza-avvia]");
  if (avvia2) {
    event.preventDefault();
    event.stopPropagation();
    const entity2 = clean(avvia2.getAttribute("data-dm-stanza-avvia"));
    const comando = entity2 && siComanda(entity2) ? comandoDelDispositivo({ entity: entity2 }) : null;
    if (!comando) return;
    root.navigator?.vibrate?.(8);
    chiamaServizio(comando);
    return;
  }
  const scegli5 = event.target?.closest?.("[data-dm-stanza-scegli]");
  if (scegli5) {
    event.preventDefault();
    event.stopPropagation();
    const entity2 = clean(scegli5.getAttribute("data-dm-stanza-scegli"));
    if (!entity2 || !siComanda(entity2)) return;
    root.navigator?.vibrate?.(8);
    apriIlMenu(entity2, {
      name: clean(scegli5.getAttribute("data-dm-stanza-nome")),
      icon: clean(scegli5.getAttribute("data-dm-stanza-segno"))
    });
    return;
  }
  if (event.target?.closest?.("[data-dm-mp],[data-dm-w-panel],.tapp-btn")) return;
  const vai = event.target?.closest?.("[data-dm-stanza-vai]");
  if (vai) {
    const entita3 = clean(vai.getAttribute("data-dm-stanza-entita"));
    if (apriLaTelecamera(entita3)) return;
    const tab = doc?.querySelector?.(`.tab[data-tab="${vai.getAttribute("data-dm-stanza-vai")}"]`);
    tab?.click?.();
    apriLaVoce(entita3);
  }
}
function installRoomsPageSection() {
  if (!doc || state48.installed) return;
  state48.installed = true;
  installStyles22();
  ensureRoomsPage();
  teachNavVisibility();
  ensureRoomsTab();
  doc.addEventListener("click", handleClick);
  doc.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    if (event.target?.closest?.("[data-dm-stanza-vai],.dm-stanze-tessera")) handleClick(event);
  });
  for (const name of ["render", "cdApplyNavVis"])
    wrapFunction(name, "__dmRoomsPageSection", schedule19);
  quandoSiCambiaPagina(schedule19);
  for (const event of [
    "dashboardmodern:legacy-ready",
    "dashboardmodern:runtime-ready",
    "dashboardmodern:states-ready",
    "dashboardmodern:state-changed",
    "dashboardmodern:persistence-restored",
    "dashboardmodern:config-reset"
  ])
    root.addEventListener?.(event, schedule19);
  doc.addEventListener("click", alToccoDellaVista, true);
  tieniIlBloccoNellaScheda("__dmStanzeVista", disegnaLaSceltaDellaVista);
  schedule19();
}
