function drawChart(chart, geometry, window, view, misura7 = misuraDelGrafico(state62.misura)) {
  chart.replaceChildren();
  const baseline = view.height - view.bottom;
  const night = svg("g", { class: "dm-trend-night" });
  for (let time = window.start; time <= window.end; time += 60 * 60 * 1e3) {
    const hour = new Date(time).getHours();
    if (hour >= 7 && hour < 20) continue;
    const from = geometry.x(time);
    const to = geometry.x(Math.min(time + 60 * 60 * 1e3, window.end));
    night.append(
      svg("rect", { x: from, y: view.top, width: Math.max(0, to - from), height: geometry.plotHeight })
    );
  }
  chart.append(night);
  if (geometry.band.visible)
    chart.append(
      svg("rect", {
        class: "dm-trend-band",
        x: view.left,
        y: geometry.band.top,
        width: geometry.plotWidth,
        height: Math.max(0, geometry.band.bottom - geometry.band.top),
        rx: 3
      })
    );
  if (geometry.band.visible) {
    const bandLabel = svg("text", {
      class: "dm-trend-band-label",
      x: view.left + 6,
      y: Math.min(geometry.band.bottom - 5, geometry.band.top + 11)
    });
    bandLabel.textContent = "comfort";
    chart.append(bandLabel);
  }
  const axis = svg("g", { class: "dm-trend-axis" });
  for (const value of tacche(geometry.min, geometry.max)) {
    const y = geometry.y(value);
    axis.append(svg("line", { x1: view.left, x2: view.width - view.right, y1: y, y2: y }));
    const label = svg("text", { x: view.left - 7, y: y + 3, class: "dm-trend-tick" });
    label.textContent = `${Number.isInteger(value) ? value : value.toFixed(1).replace(".", t(",", "."))}${misura7.unita}`;
    axis.append(label);
  }
  axis.append(
    svg("line", {
      class: "dm-trend-baseline",
      x1: view.left,
      x2: view.width - view.right,
      y1: baseline,
      y2: baseline
    })
  );
  for (const mark of hourLabels(window)) {
    const x = geometry.x(mark.time);
    const label = svg("text", { x, y: view.height - 6, class: "dm-trend-time" });
    label.textContent = mark.text;
    axis.append(label);
  }
  chart.append(axis);
  const single = geometry.series.length === 1;
  const altezzaCoda = altezzeDelleCode(
    geometry.series.map((item) => item.last.y),
    { cima: view.top + 4, fondo: view.height - view.bottom - 2 }
  );
  geometry.series.forEach((item, indice) => {
    const group = svg("g", { class: "dm-trend-series", style: `--dm-series:${item.colour}` });
    if (single) group.append(svg("path", { class: "dm-trend-area", d: item.area }));
    group.append(
      svg("path", {
        class: "dm-trend-line",
        d: item.line,
        ...item.stroke ? { "stroke-dasharray": item.stroke } : {}
      }),
      svg("circle", { class: "dm-trend-dot", cx: item.last.x, cy: item.last.y, r: 3.4 })
    );
    const y = altezzaCoda.get(indice);
    if (y != null) {
      const tag = svg("text", {
        class: "dm-trend-value",
        x: Math.min(item.last.x + 7, view.width - 4),
        y
      });
      tag.textContent = valore(item.last.value, misura7);
      group.append(tag);
    }
    chart.append(group);
  });
}
function drawLegend(legend, disegnate, tutte, spenti, misura7) {
  legend.replaceChildren();
  const conIlDisegno = new Map(disegnate.map((item) => [item.id, item]));
  for (const item of tutte) {
    const acceso6 = conIlDisegno.get(item.id) || null;
    const chip = element3("button", "dm-trend-chip");
    chip.type = "button";
    chip.dataset.dmTrendSerie = item.id;
    chip.dataset.dmSpenta = String(!acceso6);
    chip.setAttribute("aria-pressed", String(Boolean(acceso6)));
    chip.title = acceso6 ? t("Tocca per toglierla dal grafico", "Tap to drop it from the chart") : t("Tocca per rimetterla nel grafico", "Tap to put it back on the chart");
    chip.style.setProperty("--dm-series", item.colour);
    const pallino = element3("i", "dm-trend-swatch");
    if (item.stroke) pallino.dataset.dmTratto = item.stroke === "7 5" ? "tratti" : "punti";
    chip.append(pallino, element3("b", "dm-trend-chip-name", item.name));
    if (acceso6)
      chip.append(
        element3("span", "dm-trend-chip-now", valore(acceso6.last.value, misura7)),
        element3(
          "small",
          "dm-trend-chip-range",
          `${valore(acceso6.low, misura7)} · ${valore(acceso6.high, misura7)}`
        )
      );
    legend.append(chip);
  }
  legend.dataset.dmSpente = String(spenti.size);
}
function giraLaSerie(id) {
  const misura7 = misuraDelGrafico(state62.misura);
  const model2 = trendSeriesModel(rooms(), activeRoomId(), misura7);
  const stored = preferenze();
  const prossime = conLaSerieGirata(stored, model2.series, id);
  if (!prossime) {
    root.edToast?.(
      t("Almeno una deve restare nel grafico", "At least one has to stay on the chart")
    );
    return false;
  }
  writeJsonIfChanged(CHIAVE_GRAFICO_STANZE, { ...stored, spente: prossime });
  state62.signature = "";
  schedule22();
  return true;
}
function renderTemperatureTrend() {
  const panel2 = ensurePanel();
  if (!panel2) return false;
  const roomId = activeRoomId();
  const misura7 = misuraDelGrafico(state62.misura);
  const model2 = trendSeriesModel(rooms(), roomId, misura7);
  const intervallo2 = periodoDelPannello();
  panel2.querySelectorAll(".dm-trend-misura[data-dm-misura]").forEach(
    (button) => button.classList.toggle("active", button.dataset.dmMisura === misura7.chiave)
  );
  const hours = intervallo2.ore;
  panel2.querySelectorAll(".dm-trend-range[data-hours]").forEach(
    (button) => button.classList.toggle(
      "active",
      !intervallo2.personalizzato && Number(button.dataset.hours) === hours
    )
  );
  panel2.querySelector(".dm-trend-range-custom")?.classList.toggle("active", Boolean(intervallo2.personalizzato));
  panel2.querySelector(".dm-trend-title").textContent = model2.title;
  if (!model2.series.length) {
    panel2.querySelector(".dm-trend-empty").textContent = misura7.chiave === MISURE4[0].chiave ? t(
      "Nessuno storico disponibile per questa stanza.",
      "No history yet for this room."
    ) : t(
      "Nessuna stanza ha una sonda dell'umidità: si aggiunge dalla scheda Temperature.",
      "No room has a humidity probe: add one from the Temperature tab."
    );
    panel2.dataset.state = "empty";
    return false;
  }
  const window = { start: intervallo2.start, end: intervallo2.end, hours };
  const spenti = serieSpente(preferenze());
  const accese = serieAccese(model2.series, spenti);
  const withRows = accese.map((item) => ({ ...item, rows: rowsFor2(item.entity, intervallo2) }));
  if (withRows.some((item) => item.rows === null)) panel2.dataset.state = "loading";
  const view = viewFor(panel2);
  const chart = panel2.querySelector(".dm-trend-chart");
  chart.setAttribute("viewBox", `0 0 ${view.width} ${view.height}`);
  chart.style.height = `${view.height}px`;
  const geometry = trendGeometry(
    withRows.filter((item) => Array.isArray(item.rows)),
    window,
    view,
    misura7.comfort
  );
  if (!geometry) {
    panel2.dataset.state = panel2.dataset.state === "loading" ? "loading" : "empty";
    return false;
  }
  drawChart(chart, geometry, window, view, misura7);
  drawLegend(panel2.querySelector(".dm-trend-legend"), geometry.series, model2.series, spenti, misura7);
  panel2.dataset.state = "ready";
  return true;
}
function schedule22() {
  if (state62.frame) return;
  state62.frame = root.requestAnimationFrame?.(() => {
    state62.frame = 0;
    renderTemperatureTrend();
  }) || 0;
}
