async function onClick30(event) {
  const body = doc?.getElementById("ed-body");
  if (!body || activeTab3() !== ROBOT_EDITOR_TAB || !body.contains(event.target)) return;
  const robots = lista2();
  if (event.target.closest("[data-robot-integ]")) {
    event.preventDefault();
    apriMenuIntegrazioni({
      titolo: t("Aggiungi un robot da un'integrazione", "Add a robot from an integration"),
      intro: t(
        "Le integrazioni di Home Assistant, ufficiali o da HACS, con i dispositivi che portano. Scegli il tuo robot: la sua entità, le sue mappe, la batteria, i suoi programmi e le sue letture entrano da soli.",
        "Home Assistant integrations, official or from HACS, with the devices they bring. Pick your robot: its entity, its maps, the battery, its programs and its readings come along by themselves."
      ),
      anteprima: anteprimaRobot,
      onScelto: (scelta3) => creaDaDispositivo2(scelta3)
    });
    return;
  }
  if (event.target.closest("[data-robot-add]")) {
    event.preventDefault();
    state123.aperto = robots.length;
    await salva16([...robots, { id: `robot-${robots.length + 1}`, name: "", entity: "" }]);
    ridisegna9();
    return;
  }
  const pick2 = event.target.closest("[data-robot-pick]");
  if (pick2) {
    event.preventDefault();
    const input = body.querySelector(`#${CSS.escape(clean(pick2.dataset.robotPick))}`);
    if (input) root.wzPickEntity?.(input);
    return;
  }
  const riga3 = event.target.closest("[data-robot-index]");
  if (!riga3) return;
  const index = Number(riga3.dataset.robotIndex);
  if (!Number.isFinite(index) || !robots[index]) return;
  if (event.target.closest("[data-robot-edit]")) {
    event.preventDefault();
    state123.aperto = state123.aperto === index ? -1 : index;
    ridisegna9();
    return;
  }
  const proposta = event.target.closest("[data-robot-chip-sug]");
  const togli = event.target.closest("[data-robot-chip-del]");
  const aggiungi4 = event.target.closest("[data-robot-chip-add]");
  if (proposta || togli || aggiungi4) {
    event.preventDefault();
    const tocco2 = proposta || togli || aggiungi4;
    const tipo = clean(tocco2.dataset.robotChipTipo || tocco2.dataset.robotChipAdd);
    if (!LISTE[tipo]) return;
    const casella3 = tocco2.closest(`[data-robot-lista="${CSS.escape(tipo)}"]`);
    const letta = leggiRiga4(riga3, robots[index]);
    if (!/^(?:vacuum|lawn_mower)\.[a-z0-9_]+$/i.test(letta.entity))
      letta.entity = robots[index].entity;
    const errore = riga3.querySelector("[data-robot-error]");
    let elenco9 = LISTE[tipo].elenco(letta[tipo]);
    if (togli) {
      elenco9 = elenco9.filter((entity2) => entity2 !== clean(togli.dataset.robotChipDel));
    } else {
      const nuovo = proposta ? clean(proposta.dataset.robotChipSug) : clean(casella3?.querySelector("[data-robot-chip-nuovo]")?.value);
      const esito2 = conLaVoce(elenco9, nuovo, tipo);
      if (esito2.esito !== ESITI_ELENCO.aggiunto) {
        if (errore) errore.textContent = spiegazione(esito2.esito, tipo);
        return;
      }
      elenco9 = esito2.elenco;
    }
    if (errore) errore.textContent = "";
    const next = robots.slice();
    next[index] = { ...letta, [tipo]: elenco9 };
    await salva16(next);
    ridisegna9();
    return;
  }
  if (event.target.closest("[data-robot-del]")) {
    event.preventDefault();
    const domanda = t(
      `Elimino "${nomeDi10(robots[index], index)}"?`,
      `Remove "${nomeDi10(robots[index], index)}"?`
    );
    if (root.confirm && !root.confirm(domanda)) return;
    state123.aperto = -1;
    await salva16(robots.filter((_robot, position) => position !== index));
    ridisegna9();
    return;
  }
  if (event.target.closest("[data-robot-save]")) {
    event.preventDefault();
    const next = robots.slice();
    next[index] = leggiRiga4(riga3, robots[index]);
    const errore = riga3.querySelector("[data-robot-error]");
    if (!/^(?:vacuum|lawn_mower)\.[a-z0-9_]+$/i.test(next[index].entity)) {
      if (errore)
        errore.textContent = t(
          "Serve un'entità vacuum.* o lawn_mower.* valida.",
          "A valid vacuum.* or lawn_mower.* entity is required."
        );
      return;
    }
    if (errore) errore.textContent = "";
    await salva16(next);
    ridisegna9();
    root.edToast?.(t("💾 Robot salvato", "💾 Robot saved"));
  }
}
function ridisegna9() {
  const body = doc?.getElementById("ed-body");
  if (body) delete body.dataset.dmRobotEditor;
  ensureRobotEditor();
}
function ensureRobotEditorTab() {
  const tabs = doc?.querySelector(".ed-tab")?.parentElement;
  if (!tabs || tabs.querySelector(`.ed-tab[data-tab="${ROBOT_EDITOR_TAB}"]`)) return false;
  const tab = doc.createElement("button");
  tab.className = "ed-tab";
  tab.dataset.tab = ROBOT_EDITOR_TAB;
  tab.textContent = `🤖 ${t("Robot", "Robots")}`;
  tab.addEventListener("click", () => root.editorSwitch?.(ROBOT_EDITOR_TAB));
  const prima = tabs.querySelector('.ed-tab[data-tab="runtime"]');
  if (prima) prima.before(tab);
  else tabs.append(tab);
  return true;
}
