function fondoDelRadar(config = {}) {
  const niente = { modello: "", attribuzione: "" };
  const voce2 = (preset) => ({
    modello: preset.modello,
    attribuzione: stringa(preset.attribuzione)
  });
  const dellaSerie = FONDI_MAPPA[FONDO_DI_SERIE];
  let fondo = stringa(config?.fondo);
  if (NIENTE.includes(fondo.toLowerCase())) return niente;
  if (FONDI_RITIRATI[fondo]) fondo = FONDI_RITIRATI[fondo];
  if (FONDI_MAPPA[fondo]) return voce2(FONDI_MAPPA[fondo]);
  const suo2 = (indirizzo) => indirizzoRitirato(indirizzo) ? voce2(dellaSerie) : { modello: indirizzo, attribuzione: "" };
  if (fondo === "modello") {
    const mio = stringa(config?.fondoModello);
    return /\{[zxy]\}/.test(mio) ? suo2(mio) : niente;
  }
  if (/\{[zxy]\}/.test(fondo)) return suo2(fondo);
  if (!fondo) return voce2(dellaSerie);
  return niente;
}
function modelloDelFondo(config = {}) {
  return fondoDelRadar(config).modello;
}
function attribuzioneDelFondo(config = {}) {
  return fondoDelRadar(config).attribuzione;
}

// src/core/la-persona-nel-navigatore.js
var CANALE_DEL_NAVIGATORE = "gdahomeNavigatore";
function laPersonaPerIlNavigatore(view, states = {}) {
  const attributi2 = states?.[view?.entity]?.attributes || {};
  const lat = latitudine(attributi2.latitude);
  const lon = longitudine(attributi2.longitude);
  if (lat === null || lon === null) return null;
  return {
    id: String(view?.entity ?? ""),
    nome: String(view?.name ?? "").trim() || String(view?.entity ?? ""),
    lat,
    lon,
    indirizzo: String(view?.address ?? "").trim()
  };
}
function cIlNavigatore(root7 = globalThis) {
  return typeof root7?.[CANALE_DEL_NAVIGATORE]?.postMessage === "function";
}
function mandaLaPersonaAlNavigatore(view, states, root7 = globalThis) {
  const canale = root7?.[CANALE_DEL_NAVIGATORE];
  if (typeof canale?.postMessage !== "function") return false;
  const messaggio = laPersonaPerIlNavigatore(view, states);
  if (!messaggio) return false;
  try {
    canale.postMessage(JSON.stringify(messaggio));
    return true;
  } catch (_errore) {
    return false;
  }
}

