  scatola: "left:50%;top:50%",
  casa: `left:min(88%,100% - ${RIENTRO});top:50%`,
  carico: "left:50%;top:12%",
  autonomia: "left:50%;top:88%",
  tensione: "left:14%;top:18%",
  potenza: "left:86%;top:18%",
  temperatura: "left:86%;top:82%",
