function installStyles82() {
  installStyle(
    "dm-sezioni-mie",
    `
      .page[id^="page-mia-"] .dm-mia-wrap{display:grid;gap:16px;padding:0 0 24px}
      .dm-mia-lista{display:grid;gap:10px}
      .dm-mia-riga{
        display:grid;grid-template-columns:44px minmax(0,1fr) auto auto;align-items:center;gap:12px;
        padding:12px 14px;border-radius:18px;
        background:var(--card-background-color,#fff);border:1px solid var(--card-border,#e2e8f0);
        box-shadow:0 10px 24px -20px rgba(15,23,42,.5)}
      .dm-mia-riga[data-muta="true"]{opacity:.55}
      .dm-mia-ic{
        display:grid;place-items:center;width:44px;height:44px;border-radius:14px;font-size:19px;
        background:var(--bg-sculpted,#f0f4f8)}
      .dm-mia-riga[data-on="true"] .dm-mia-ic{
        background:color-mix(in srgb,#f97316 16%,transparent)}
      .dm-mia-nome{display:grid;min-width:0}
      .dm-mia-nome strong{
        font-size:14px;font-weight:800;color:var(--text,#0f172a);
        overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
      .dm-mia-val b{font-size:17px;font-weight:900;color:var(--text,#0f172a);white-space:nowrap}
      .dm-mia-val b small{font-size:11px;font-weight:800;color:var(--text-dim,#64748b)}
      .dm-mia-val .dm-mia-muta{font-size:12px;font-weight:800;color:var(--text-dim,#64748b)}
      .dm-mia-riga[data-on="true"] .dm-mia-val b{color:#ea580c}
      /* La coda della riga: quello che la voce ha da dare, tutto in una casella.
       *
       * Un'automazione ne ha due — il tasto che la fa partire e la levetta che
       * la abilita (#552) — e i figli della riga devono restare quattro, o la
       * griglia manda a capo il quinto. */
      .dm-mia-coda{display:flex;align-items:center;gap:8px;justify-content:flex-end}
      /* Il tasto «fai partire»: si legge come un tasto, non come una levetta.
       * Tondo e pieno contro la levetta allungata, cosi' i due gesti non si
       * scambiano sotto il pollice. */
      .dm-mia-parti{
        width:30px;height:30px;flex:0 0 auto;border:0;border-radius:50%;cursor:pointer;
        font-size:11px;line-height:1;color:#fff;
        background:linear-gradient(135deg,#38bdf8,#0284c7);
        box-shadow:0 2px 6px rgba(2,132,199,.35)}
      .dm-mia-parti:active{transform:scale(.92)}
      /* I tre puntini stanno nello stesso tondo del «fai partire» — una riga
         alta uguale all'altra e' meta' del mestiere — ma non nello stesso
         colore: quello e' il blu di «adesso parte», e questo e' un elenco che
         si apre. E il disegno e' stretto e alto: alla misura della freccia si
         vedrebbe come un granello. */
      .dm-mia-scegli{
        font-size:17px;font-weight:900;color:var(--text,#0f172a);
        background:var(--bg-sculpted,#e2e8f0);box-shadow:none}
      .dm-mia-lev{
        position:relative;width:46px;height:26px;border:0;border-radius:999px;cursor:pointer;
        background:var(--bg-sculpted,#cbd5e1);transition:background .25s ease}
      .dm-mia-lev i{
        position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:#fff;
        box-shadow:0 2px 6px rgba(15,23,42,.25);transition:transform .25s cubic-bezier(.16,1,.3,1)}
      .dm-mia-riga[data-on="true"] .dm-mia-lev{background:linear-gradient(135deg,#fb923c,#ea580c)}
      .dm-mia-riga[data-on="true"] .dm-mia-lev i{transform:translateX(20px)}
      @media(max-width:560px){
        /* La coda si misura su quello che contiene: da quando un'automazione
         * porta anche il tasto «fai partire», 46 px fissi le stavano stretti. */
        .dm-mia-riga{grid-template-columns:38px minmax(0,1fr) auto auto;gap:9px;padding:10px 11px}
        .dm-mia-ic{width:38px;height:38px;font-size:17px}
      }

      /* Piccole (#515): la stessa voce, stretta.
       *
       * «Si potrebbe poter scegliere il tipo di scheda? Magari averle piu'
       * piccole.» Piccole vuol dire due cose insieme, e servono tutt'e due:
       * piu' bassa la singola voce, e piu' voci per riga. Una sola delle due
       * non basta — voci basse a tutta larghezza restano una colonna, e voci
       * affiancate ma piu' alte occupano lo stesso posto di prima in verticale.
       *
       * Resta su UN piano, come quella di sempre: icona, nome, e in fondo
       * quello che la voce ha da dare. Che e' sempre una cosa sola — un
       * interruttore ha la leva e non ha un numero, un sensore ha il numero e
       * non ha la leva — quindi la colonna in fondo basta per tutt'e due, e
       * mandare il valore su un secondo piano allungherebbe la tessera invece
       * di accorciarla. L'entita' sotto il nome se ne va: in una tessera
       * stretta e' una fila di puntini.
       *
       * Il minimo e' 150 px: sotto, il nome di un'entita' non ci sta. */
      .dm-mia-lista[data-formato="piccole"]{
        grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px}
      /* Quattro colonne perche' i figli sono quattro, sempre: icona, nome,
       * valore e leva — e dove uno dei due ultimi non c'e' arriva comunque il
       * suo posto vuoto. Con tre colonne il quarto figlio andava a capo, e la
       * leva finiva sotto il nome: la tessera diventava alta il doppio, cioe'
       * l'opposto di quello che si era chiesto. Le due code sono «auto»:
       * quella che non ha niente da dire non occupa niente. */
      .dm-mia-lista[data-formato="piccole"] .dm-mia-riga{
        grid-template-columns:32px minmax(0,1fr) auto auto;gap:9px;padding:8px 11px;
        border-radius:14px}
      .dm-mia-lista[data-formato="piccole"] .dm-mia-ic{width:32px;height:32px;font-size:15px;border-radius:11px}
      .dm-mia-lista[data-formato="piccole"] .dm-mia-nome strong{font-size:12.5px}
      .dm-mia-lista[data-formato="piccole"] .dm-mia-val b{font-size:14px}
      .dm-mia-lista[data-formato="piccole"] .dm-mia-lev{width:38px;height:22px}
      .dm-mia-lista[data-formato="piccole"] .dm-mia-lev i{width:16px;height:16px}
      .dm-mia-lista[data-formato="piccole"] .dm-mia-riga[data-on="true"] .dm-mia-lev i{
        transform:translateX(16px)}
      /* Il posto vuoto di chi non ha leva non allarga la tessera. */
      .dm-mia-lista[data-formato="piccole"] .dm-mia-vuoto{width:0}
      .dm-mia-lista[data-formato="piccole"] .dm-mia-coda{gap:6px}
      .dm-mia-lista[data-formato="piccole"] .dm-mia-parti{width:26px;height:26px;font-size:10px}
      .dm-mia-lista[data-formato="piccole"] .dm-mia-scegli{font-size:15px}
      @media(max-width:560px){
        .dm-mia-lista[data-formato="piccole"]{grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}
        .dm-mia-lista[data-formato="piccole"] .dm-mia-riga{
          grid-template-columns:28px minmax(0,1fr) auto auto;gap:7px;padding:7px 9px}
        .dm-mia-lista[data-formato="piccole"] .dm-mia-ic{width:28px;height:28px;font-size:14px}
      }
    `
  );
}
function installSezioniMie() {
  if (!doc || state158.installed) return false;
  state158.installed = true;
  installStyles82();
  doc.addEventListener("click", onClick48);
  for (const nome of ["render", "cdApplyNavVis"]) {
    const precedente = root[nome];
    if (typeof precedente !== "function" || precedente.__dmSezioniMie) continue;
    const avvolta = function(...args) {
      const esito2 = precedente.apply(this, args);
      schedule40();
      return esito2;
    };
    Object.assign(avvolta, precedente);
    avvolta.__dmSezioniMie = true;
    avvolta.__dmPrevious = precedente;
    root[nome] = avvolta;
  }
  for (const evento of [
    "dashboardmodern:states-ready",
    "dashboardmodern:state-changed",
    "dashboardmodern:persistence-restored",
    "dashboardmodern:legacy-ready"
  ])
    root.addEventListener?.(evento, schedule40);
  schedule40();
  return true;
}

